<?php if(!defined('TELEDRIVE_INIT')){exit('Direct access not permitted');}class Auth{const MAX_ATTEMPTS=5;const LOCKOUT_SECONDS=900;const SESSION_LIFETIME=43200;public static function check():bool{if(!isset($_SESSION['teledrive_authenticated'])||$_SESSION['teledrive_authenticated']!==true){return false;}$lastActivity=(int)($_SESSION['teledrive_last_activity']??0);if($lastActivity>0&&(time()-$lastActivity)>self::SESSION_LIFETIME){self::logout();return false;}$expectedSignature=hash_hmac('sha256',$_SESSION['teledrive_user']??'',SESSION_SECRET);if(!isset($_SESSION['teledrive_token'])|| !hash_equals($_SESSION['teledrive_token'],$expectedSignature)){return false;}$_SESSION['teledrive_last_activity']=time();return true;}public static function login(string $username,string $password):bool{$attemptKey='teledrive_login_attempts';$lockoutKey='teledrive_lockout_until';$lockoutUntil=(int)($_SESSION[$lockoutKey]??0);if($lockoutUntil>0&&time()<$lockoutUntil){return false;}$validUser=ADMIN_USER;$validHash=ADMIN_PASSWORD_HASH;$userMatch=hash_equals($validUser,$username);$passMatch=password_verify($password,$validHash);if(!$userMatch|| !$passMatch){$_SESSION[$attemptKey]=(int)($_SESSION[$attemptKey]??0)+1;if($_SESSION[$attemptKey]>=self::MAX_ATTEMPTS){$_SESSION[$lockoutKey]=time()+self::LOCKOUT_SECONDS;$_SESSION[$attemptKey]=0;}return false;}unset($_SESSION[$attemptKey],$_SESSION[$lockoutKey]);session_regenerate_id(true);$_SESSION['teledrive_authenticated']=true;$_SESSION['teledrive_user']=$username;$_SESSION['teledrive_token']=hash_hmac('sha256',$username,SESSION_SECRET);$_SESSION['teledrive_login_time']=time();$_SESSION['teledrive_last_activity']=time();return true;}public static function getLockoutRemaining():int{$lockoutUntil=(int)($_SESSION['teledrive_lockout_until']??0);if($lockoutUntil>0&&time()<$lockoutUntil){return $lockoutUntil-time();}return 0;}public static function logout():void{$_SESSION=[];if(ini_get('session.use_cookies')){$params=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$params['path'],$params['domain'],$params['secure'],$params['httponly']);}session_destroy();}public static function requireAuth():void{if(!self::check()){Helpers::error('Unauthorized. Please login.',401);}}public static function getCsrfToken():string{if(empty($_SESSION['teledrive_csrf_token'])){$_SESSION['teledrive_csrf_token']=bin2hex(random_bytes(32));}return $_SESSION['teledrive_csrf_token'];}public static function verifyCsrf(string $submittedToken):bool{$expected=$_SESSION['teledrive_csrf_token']??'';return!empty($expected)&&hash_equals($expected,$submittedToken);}}